      <MenuProvider
        label={label}
        formatItemLabel={formatItemLabel}
        items={options}
        role="listbox"
        keyboardInteractions="form-control"
        placement="bottom-start"
        offset={0} // Make the dropdown flush with the select element
        defaultSelected={defaultSelected}
        selected={selected}
        onSelect={onSelect}
