      {...propsRest}
      className={cx(
        { [cl['bk-list-box__item']]: !unstyled },
        cl['bk-list-box__item--static'],
        cl['bk-list-box__item--header'],
        { [cl['bk-list-box__item--sticky-start']]: sticky === 'start' },
        propsRest.className,
